ALTER TABLE public.book_orders ADD COLUMN payment_intent_id text, ADD COLUMN payment_currency text, ADD COLUMN payment_tax_cents integer, ADD COLUMN payment_hold text, ADD COLUMN payment_event_at timestamptz, ADD COLUMN checkout_lease uuid, ADD COLUMN checkout_lease_at timestamptz;
CREATE INDEX book_payment_intent_idx ON public.book_orders(payment_intent_id) WHERE payment_intent_id IS NOT NULL;
CREATE FUNCTION public.reserve_book_checkout(p_order uuid,p_owner uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE token uuid; BEGIN UPDATE public.book_orders SET checkout_lease=gen_random_uuid(),checkout_lease_at=now() WHERE id=p_order AND user_id=p_owner AND status IN ('draft','awaiting_payment') AND payment_hold IS NULL AND (checkout_lease_at IS NULL OR checkout_lease_at<now()-interval '2 minutes') RETURNING checkout_lease INTO token; RETURN token; END $$;
REVOKE ALL ON FUNCTION public.reserve_book_checkout(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reserve_book_checkout(uuid,uuid) TO service_role;
CREATE FUNCTION public.guard_book_payment_evidence() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user<>'service_role' THEN IF TG_OP='INSERT' THEN IF NEW.payment_intent_id IS NOT NULL OR NEW.payment_currency IS NOT NULL OR NEW.payment_tax_cents IS NOT NULL OR NEW.payment_hold IS NOT NULL OR NEW.payment_event_at IS NOT NULL OR NEW.checkout_lease IS NOT NULL OR NEW.checkout_lease_at IS NOT NULL THEN RAISE EXCEPTION 'Payment evidence is server managed'; END IF; ELSE IF NEW.payment_intent_id IS DISTINCT FROM OLD.payment_intent_id OR NEW.payment_currency IS DISTINCT FROM OLD.payment_currency OR NEW.payment_tax_cents IS DISTINCT FROM OLD.payment_tax_cents OR NEW.payment_hold IS DISTINCT FROM OLD.payment_hold OR NEW.payment_event_at IS DISTINCT FROM OLD.payment_event_at OR NEW.checkout_lease IS DISTINCT FROM OLD.checkout_lease OR NEW.checkout_lease_at IS DISTINCT FROM OLD.checkout_lease_at THEN RAISE EXCEPTION 'Payment evidence is server managed'; END IF; END IF; END IF; IF NEW.payment_hold IS NOT NULL AND NEW.status IN ('printing','shipped','delivered') AND (TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status) THEN RAISE EXCEPTION 'Resolve payment hold before fulfillment'; END IF; IF TG_OP='UPDATE' AND NEW.status='delivered' AND OLD.status NOT IN ('shipped','delivered') THEN RAISE EXCEPTION 'Dispatch before marking delivered'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_book_payment_evidence BEFORE INSERT OR UPDATE ON public.book_orders FOR EACH ROW EXECUTE FUNCTION public.guard_book_payment_evidence();